const current = $input.first().json;
function parseResponse(raw) {
  if (raw.error) throw new Error('MODEL_CALL_FAILED');
  if (raw.status && raw.status !== 'completed') throw new Error('MODEL_OUTPUT_INCOMPLETE');
  const texts = [];
  for (const output of Array.isArray(raw.output) ? raw.output : []) {
    if (output.status && output.status !== 'completed') throw new Error('MODEL_OUTPUT_INCOMPLETE');
    for (const part of Array.isArray(output.content) ? output.content : []) {
      if (part.type === 'refusal' || part.refusal) throw new Error('MODEL_REFUSAL');
      if (typeof part.text === 'string') texts.push(part.text);
    }
  }
  if (!texts.length && typeof raw.output_text === 'string') texts.push(raw.output_text);
  if (texts.length !== 1) throw new Error('MODEL_OUTPUT_INVALID');
  const text = texts[0].trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const result = JSON.parse(text);
  if (!result || typeof result !== 'object' || Array.isArray(result)) throw new Error('MODEL_OUTPUT_INVALID');
  return result;
}

const c = $('Antwortkontext empfangen').first().json.context;
try {
  const d = parseResponse(current);
  const allowed = new Set(c.articles.map(a => a.article_id));
  if (typeof d.draft !== 'string' || !d.draft.trim() || d.draft.length > 6000
      || d.draft.includes('\u0000')
      || !Array.isArray(d.source_article_ids) || !d.source_article_ids.length
      || !d.source_article_ids.every(id => typeof id === 'string' && allowed.has(id))
      || !Array.isArray(d.open_questions) || d.open_questions.length > 10
      || !d.open_questions.every(q => typeof q === 'string' && q.length <= 500 && !q.includes('\u0000'))) throw new Error('DRAFT_SCHEMA_INVALID');
  const reasons = [];
  if (c.analysis.category === 'billing') reasons.push('BILLING_REQUIRES_REVIEW');
  if (c.analysis.needs_review) reasons.push('MODEL_REQUESTS_REVIEW');
  if (c.analysis.risk_flags.length) reasons.push('RISK_FLAGS_PRESENT');
  if (c.analysis.missing_information.length || d.open_questions.length) reasons.push('MISSING_INFORMATION');
  if (['high','critical'].includes(c.analysis.priority)) reasons.push('HIGH_PRIORITY');
  // Auto nur für einen eng definierten Routinefall und einen unveränderten
  // freigegebenen Text. Freie Modellformulierungen bleiben prüfpflichtig.
  const message = c.request.message.replace(/\s+/g, ' ').trim();
  const subject = c.request.subject.toLocaleLowerCase('de-DE');
  const template = c.articles.find(a => a.article_id === 'KB001');
  const routine = subject === 'passwort vergessen'
    && /^wie kann ich mein passwort zurücksetzen\??$/i.test(message)
    && c.analysis.category === 'login'
    && c.articles.length === 1 && !!template
    && c.analysis.article_ids.length === 1 && c.analysis.article_ids[0] === 'KB001'
    && reasons.length === 0;
  if (!routine) reasons.push('GENERATED_DRAFT_REQUIRES_REVIEW');
  return [{json: {...c,
    analysis: {...c.analysis, open_questions: d.open_questions,
      draft_mode: routine ? 'approved_template' : 'llm'},
    source_article_ids: routine ? ['KB001'] : [...new Set(d.source_article_ids)],
    draft: routine ? template.content : d.draft,
    decision: routine ? 'auto' : 'review',
    status: routine ? 'ready_for_auto_reply' : 'needs_review',
    reason_codes: routine ? ['APPROVED_PASSWORD_RESET_TEMPLATE'] : [...new Set(reasons)],
    error_code: null, error_message: null}}];
} catch (error) {
  return [{json: {...c, draft: null, decision: 'review', status: 'technical_error',
    reason_codes: ['DRAFT_FAILED'], error_code: 'DRAFT_FAILED',
    error_message: 'KI-Aufruf oder Antwortentwurf ungültig. Execution prüfen.'}}];
}
